{"id":"0192570d-2d46-73a1-9269-caca6da0c53f","name":"ÜSTRA","domain":"uestra.de","website":"https://uestra.de","type":"public","legalName":null,"industry":"Transportation","industries":["Transportation/Rail, Bus & Taxi"],"categories":["b2c","b2g","service-provider"],"employees":"51-200","reported_employees":"1K-5K","revenue":null,"description":"ÜSTRA is the public transport operator for the Hannover region, providing urban bus and tram services and Fahrplanauskunft (timetable information) to help residents and visitors travel across the region. The company offers fare tariffs, ticketing options—including Deutschlandticket-related offerings—and mobility services such as helpful customer support and accessibility initiatives for barrier-free travel. Headquartered and primarily serving the Hannover metropolitan area, ÜSTRA collaborates with regional partners to maintain reliable and environmentally friendly public transportation.","keywords":["public transport hannover","regional tram and bus","fahrplanauskunft","fahrkarten preise","deutschlandticket","hannover tarife","mobilität hannover","barrierefreies reisen","begleitservice","sprintRad","fahrradmitnahme","mobilitätangebote","verkehrsverbund hannover","öffentlicher nahverkehr","öffentliche verkehrsmittel","nähe zivilgesellschaft","kundendienst hannover","verkehrsinformation","öffentliche verkehrsmittel hannover","public transportation","transit services","employee diversity","community services","urban mobility","transportation"],"technologies":["Outlook","Microsoft Office 365","Microsoft-IIS","SoundCloud","Mobile Friendly","YouTube","Apache","DoubleClick Conversion"],"subsidiaries":null,"founded_year":1892,"naics_codes":["485111","485112"],"location":{"country":{"code":"DE","name":"Germany","latitude":51,"longitude":9},"state":{"id":1383,"name":"Lower Saxony","code":"NI","latitude":52.636703,"longitude":9.845077},"city":{"id":38133,"name":"Hannover","latitude":52.37052,"longitude":9.73322},"address":"Am Hohen Ufer 6, Hannover, Niedersachsen, Deutschland","postal_code":"30159","phone":"+49 511 1668 0"},"financial":{"stock_symbol":"HVB.F","stock_exchange":null,"total_funding":null,"funding_stage":null,"funding_date":null,"funding":null},"socials":{"linkedin_url":"https://www.linkedin.com/company/-stra-hannoversche-verkehrsbetriebe-ag","linkedin_id":"5431221","twitter_url":"https://twitter.com/uestra","facebook_url":"https://www.facebook.com/uestra","instagram_url":"https://www.instagram.com/uestra/","angellist_url":null,"crunchbase_url":null,"youtube_url":"https://www.youtube.com/@ustrahannoverscheverkehrsb5244","github_url":null,"g2_url":null},"page_rank":2.9305255,"logo_url":"https://api.companyenrich.com/companies/logo/0192570d-2d46-73a1-9269-caca6da0c53f","seo_description":"ÜSTRA Hannoversche Verkehrsbetriebe AG is the main public transport operator in Hannover, Germany, and its surrounding areas. The company runs a network of buses, trams, and local rail services that connect Hannover with nearby towns and districts, promoting efficient urban and regional mobility.

The services include light rail and tram connections within Hannover and to municipalities like Langenhagen and Laatzen, as well as bus services that enhance the rail network. ÜSTRA integrates with regional and suburban trains from other operators, ensuring seamless travel across the region. The company also offers a digital ticketing system through its app, allowing customers to purchase tickets and access real-time travel information easily.

Additional customer services include bicycle transport options on buses and trains, a service center for support and ticketing, and mobility solutions like taxi bookings and car-sharing, all integrated within the app. ÜSTRA caters to residents, visitors, and trade fair attendees, providing comprehensive public transport solutions for daily commuting and leisure travel.","updated_at":"2026-08-13T21:57:01.641363Z"}

