{"id":"019252ae-02a2-7535-af46-0f692d93bdc4","name":"HEUFT","domain":"heuft.com","website":"https://heuft.com","type":"private","legalName":"HEUFT SYSTEMTECHNIK GMBH","industry":"Manufacturing","industries":["Manufacturing/Industrial Machinery & Equipment","Manufacturing/Medical Devices & Equipment","Manufacturing/Photographic & Optical Equipment","Manufacturing/Test & Measurement Equipment"],"categories":["b2b"],"employees":"51-200","reported_employees":"1K-5K","revenue":"50m-100m","description":"HEUFT develops modular quality assurance, inspection, labeling, rejection, and container transport systems for beverage, food, and pharmaceutical production lines. Its technologies support product and package inspection, optical and X-ray detection, track and trace, and production-line efficiency. The company serves manufacturers internationally through a global service and subsidiary network.","keywords":["quality assurance","beverage production","food production","pharmaceutical production","packaging inspection","product inspection","container inspection","empty bottle inspection","empty can inspection","full container inspection","package inspection","optical inspection","X-ray inspection","pulsed X-ray technology","foreign object detection","glass-in-glass detection","optical character verification","AI image processing","deep learning","label inspection","labelling systems","fault rejection","rejection systems","container transport","filling lines","packaging lines","production-line optimization","track and trace","real-time data management","pharmaceutical packaging inspection","medical device inspection","primary pharmaceutical packaging","remote service","industrial automation","packaging","filling technology","quality control","pharmaceuticals","food processing","beverage industry"],"technologies":["Apache","Mobile Friendly","Remote","Ubuntu","Bootstrap Framework","Matomo","Php"],"subsidiaries":null,"founded_year":1979,"naics_codes":["333993","334513"],"location"