{"id":"01925471-a8d6-7803-8568-9662d4d9b30d","name":"HanseYachts AG","domain":"hanseyachtsag.com","website":"https://hanseyachtsag.com","type":"public","legalName":null,"industry":"Manufacturing","industries":["Manufacturing/Boats & Submarines","Manufacturing"],"categories":["b2b","b2c","media"],"employees":"11-50","reported_employees":"1K-5K","revenue":"50m-100m","description":"HanseYachts AG is a leading German yacht manufacturer specializing in sailing yachts and motor yachts. The company designs, engineers, and exports a wide range of boats globally, emphasizing performance, seaworthiness, and craftsmanship. With decades in business and over 14,000 yachts delivered, HanseYachts operates from Germany and markets through a global network of dealers and branded divisions including Hanse, Dehler, Fjord, Moody, Sealine, and Ryck.","keywords":["sailing yachts","motor yachts","yacht manufacturing","shipbuilding","german engineering","global yacht export","yacht brands","yacht design","performance sailing","seaworthiness","yacht craftsmanship","industrial yacht design","deck and hull construction","luxury yachts","maritime engineering","deck layouts","german engineering heritage","global yacht distribution","brand portfolio","yachting","sailing","boat manufacturing","luxury yachting","manufacturing"],"technologies":["Amazon AWS","Amazon CloudFront","Google Analytics","Microsoft Office 365","Outlook","Route 53","Google Tag Manager","DoubleClick","Mobile Friendly","Amazon-Cloudfront","Amazon-Ecs","Apache","Microsoft-Azure-Cdn","Php","Typo3-Cms"],"subsidiaries":null,"founded_year":1990,"naics_codes":["336612","336611","336999"],"location":{"country":{"code":"DE","name":"Germany","latitude":51,"longitude":9},"state":{"id":1384,"name":"Mecklenburg-Vorpommern","code":"MV","latitude":53.61265,"longitude":12.429595},"city":{"id":38663,"name":"Greifswald","latitude":54.09311,"longitude":13.38786},"address":"Ladebower Chaussee 11, 17493 Greifswald, Germany","postal_code":"17493",